  const defaults={schoolName:'北京印刷学院校历',schoolCalendarId:'BPI-2025-2026-2',calendarSource:'school_calendar',academicYear:'2025—2026',termType:'春季',termStartDate:'2026-03-02',termEndDate:'2026-06-19',firstClassDate:'2026-03-02',teachingWeekCount:'16',defaultHoursPerWeek:'3',weekNumberingRule:'monday',classWeekdays:['周一'],status:'active',effectiveAt:'2026-02-20'};
  const read=()=>{let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{};const c=Object.assign({},defaults,saved);if(!Array.isArray(c.classWeekdays))c.classWeekdays=[];return c};
